<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,ApiError,setCSRF,write,type State,type Revision,type Kind,type Role,type Release,type Execution} from './api';
const roleNames:Record<Role,string>={admin:'超级管理员',editor:'内容编辑',reviewer:'审核员',publisher:'发布负责人',operator:'运行人员',viewer:'只读观察员'};
const kindNames:Record<Kind,string>={asset:'素材',character:'角色',content:'内容',event:'事件'};
const stateNames:Record<string,string>={draft:'草稿',in_review:'待审核',approved:'已批准',rejected:'已驳回'};
const pages=[['overview','工作台','◈'],['asset','素材库','▧'],['character','角色','♧'],['content','内容','▤'],['event','事件','⌁'],['review','审核','✓'],['publish','发布','↗'],['runtime','消费预览','▷'],['audit','操作记录','≡'],['users','管理员','⊙']];
const page=ref(location.hash.slice(1)||'overview'),state=ref<State|null>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),preview=ref(false),selected=ref(''),loginRole=ref<Role>('editor'),username=ref(''),password=ref('');
const form=ref({name:'',persona:'',voice:'Cherry',asset_revision:'',text:'',character_revision:'',content_revision:'',trigger:'manual',cooldown_seconds:0,ttl_seconds:3600,local_time:'12:00',hook:'daily.interaction'});
const file=ref<File|null>(null),fileInput=ref<HTMLInputElement|null>(null),reviewNote=ref(''),channel=ref('preview'),releaseName=ref(''),releaseReason=ref(''),checked=ref<string[]>([]),userForm=ref({username:'',password:'',role:'editor' as Role});
const dialog=ref<HTMLDialogElement|null>(null),confirmation=ref<{title:string;action:string;payload:Record<string,unknown>}|null>(null),reason=ref(''),runtimeRelease=ref<Release|null>(null),lastExecution=ref<Execution['result']|null>(null);
const can=(permission:string)=>state.value?.permissions.includes(permission)||false;
const isKind=computed(()=>['asset','character','content','event'].includes(page.value));
const current=computed(()=>state.value?.revisions.find(r=>r.id===selected.value));
const title=computed(()=>pages.find(([id])=>id===page.value)?.[1]||'工作台');
const objects=computed(()=>state.value?.objects.filter(o=>o.kind===page.value)||[]);
const pending=computed(()=>state.value?.revisions.filter(r=>r.state==='in_review')||[]);
const approved=computed(()=>state.value?.revisions.filter(r=>r.state==='approved')||[]);
const currentChannel=computed(()=>state.value?.channels.find(c=>c.name===channel.value));
const published=computed(()=>state.value?.releases.find(r=>r.id===currentChannel.value?.release_id));
const approvedOf=(kind:Kind)=>approved.value.filter(r=>r.kind===kind);
const stamp=(date:string)=>new Date(date).toLocaleString('zh-CN',{hour12:false});
const label=(r:Revision)=>`${r.name} · v${r.number} · ${stateNames[r.state]}`;
const revisionName=(id:string)=>{const r=state.value?.revisions.find(x=>x.id===id);return r?label(r):id};
const imageURL=(digest:unknown)=>'/api/admin/blobs/'+String(digest);
const safeImage=(r:Revision)=>r.kind==='asset'&&String(r.payload.media_type).startsWith('image/');
function route(id:string){page.value=id;location.hash=id;selected.value='';error.value='';resetForm()}
window.addEventListener('hashchange',()=>{page.value=location.hash.slice(1)||'overview'});
function resetForm(){form.value={name:'',persona:'',voice:'Cherry',asset_revision:approvedOf('asset')[0]?.id||'',text:'',character_revision:approvedOf('character')[0]?.id||'',content_revision:approvedOf('content')[0]?.id||'',trigger:'manual',cooldown_seconds:0,ttl_seconds:3600,local_time:'12:00',hook:'daily.interaction'};file.value=null;if(fileInput.value)fileInput.value.value=''}
function choose(r:Revision){selected.value=r.id;form.value={...form.value,...r.payload,name:r.name};reviewNote.value='';file.value=null}
async function guarded(task:()=>Promise<void>){error.value='';busy.value=true;try{await task()}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===401)state.value=null}finally{busy.value=false}}
async function refresh(){loading.value=true;try{const data=await api<State>('/api/admin/state');state.value=data;setCSRF(data.user.csrf)}catch(e){if(e instanceof ApiError&&e.status===401)state.value=null;else error.value=e instanceof Error?e.message:'读取失败'}finally{loading.value=false}}
async function login(){await guarded(async()=>{await api('/api/admin/login',{username:username.value,password:password.value});password.value='';await refresh();resetForm()})}
async function previewLogin(role:Role){await guarded(async()=>{await api('/api/admin/preview-login',{role});await refresh();resetForm();notice.value=`已进入${roleNames[role]}预览身份`})}
async function logout(){await guarded(async()=>{await api('/api/admin/logout',{});state.value=null;setCSRF('')})}
async function mutate(action:string,payload:unknown,message:string){await write(action,payload);await refresh();notice.value=message}
async function save(){await guarded(async()=>{
 const kind=page.value as Kind;const r=current.value;const obj=state.value?.objects.find(x=>x.id===r?.object_id);
 const base={name:form.value.name,...(r?{object_id:r.object_id,expected_head:obj?.head}: {})};
 let result:{revision_id:string};
 if(kind==='asset'){
  if(!file.value)throw new Error('请选择素材文件');if(file.value.size>32*1024*1024)throw new Error('文件超过 32MB');
  const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file.value!)});
  result=await write('upload',{...base,filename:file.value.name,data});
 }else{
  const f=form.value;const payload=kind==='character'?{persona:f.persona,voice:f.voice,asset_revision:f.asset_revision}:kind==='content'?{text:f.text,character_revision:f.character_revision}:{content_revision:f.content_revision,trigger:f.trigger,target:'app_preview',cooldown_seconds:Number(f.cooldown_seconds),ttl_seconds:Number(f.ttl_seconds),...(f.trigger==='daily_time'?{local_time:f.local_time}:{}),...(f.trigger==='game_hook'?{hook:f.hook}:{})};
  result=await write('save',{...base,kind,payload});
 }
 await refresh();selected.value=result.revision_id;notice.value='草稿版本已保存';
})}
async function submit(r:Revision){await guarded(()=>mutate('submit',{revision_id:r.id},'已提交审核'))}
async function review(decision:string){if(!current.value)return;await guarded(()=>mutate('review',{revision_id:current.value!.id,decision,reason:reviewNote.value},decision==='approved'?'审核通过':'已驳回'))}
function confirm(title:string,action:string,payload:Record<string,unknown>){confirmation.value={title,action,payload};reason.value='';dialog.value?.showModal()}
async function confirmed(){const c=confirmation.value;if(!c)return;await guarded(async()=>{await mutate(c.action,{...c.payload,reason:reason.value},'操作已完成');dialog.value?.close();if(page.value==='runtime')await loadRuntime()})}
function publish(){confirm('发布到当前环境','publish',{name:releaseName.value,revision_ids:checked.value,channel:channel.value,expected_release_id:currentChannel.value?.release_id||null}) ;reason.value=releaseReason.value}
async function loadRuntime(){const result=await api<{release:Release|null}>(`/api/runtime/release?channel=${channel.value}`);runtimeRelease.value=result.release;lastExecution.value=null}
async function execute(id:string){await guarded(async()=>{const result=await write<{result:Execution['result']}>('execute',{channel:channel.value,release_id:runtimeRelease.value?.id,revision_id:id});lastExecution.value=result.result;await refresh();notice.value='本地预览已完成，未发送实体设备'})}
async function moreAudit(){await guarded(async()=>{if(!state.value)return;const data=await api<State>(`/api/admin/state?audit_after=${state.value.audit_next}`);state.value.audit.push(...data.audit);state.value.audit_next=data.audit_next;notice.value=data.audit.length?'已加载操作记录':'已经是全部记录'})}
async function createUser(){await guarded(async()=>{await mutate('create_user',userForm.value,'管理员已创建');userForm.value.password='';userForm.value.username=''})}
watch(page,async p=>{if(p==='runtime'&&state.value)await guarded(loadRuntime)});
watch(channel,async()=>{if(page.value==='runtime'&&state.value)await guarded(loadRuntime)});
onMounted(async()=>{const config=await api<{preview:boolean}>('/api/admin/config');preview.value=config.preview;await refresh();resetForm();if(page.value==='runtime'&&state.value)await guarded(loadRuntime)});
</script>

<template>
 <div v-if="!state" class="login-shell">
  <div class="login-brand"><div class="brand-mark">◈</div><span>AIapp / 角色工坊</span><h1>让角色内容<br>有序走向发布。</h1><p>素材、角色、事件，在同一条版本链上协作。</p><div class="login-steps">创建　→　审核　→　发布　→　验证</div></div>
  <div class="login-card"><span class="eyebrow">MANAGEMENT WORKSPACE</span><h2>登录工作台</h2>
   <form @submit.prevent="login"><label>用户名<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy">登录</button></form>
   <div v-if="preview" class="preview-login"><h3>本地角色预览</h3><p>可切换身份检查权限。仅本机启用。</p><label>预览身份<select v-model="loginRole"><option v-for="(n,r) in roleNames" :key="r" :value="r">{{n}}</option></select></label><button @click="previewLogin(loginRole)" :disabled="busy">进入预览</button></div>
   <p v-if="error" role="alert" class="error">{{error}}</p>
  </div>
 </div>
 <div v-else class="workspace">
  <aside><a href="#overview" class="brand" @click.prevent="route('overview')"><span class="brand-mark">◈</span><div>角色工坊<small>AIapp · 内容工作台</small></div></a><span class="nav-label">工作空间</span><nav><button v-for="[id,n,icon] in pages.filter(p=>p[0]!=='users'||can('users'))" :key="id" :class="{active:page===id}" @click="route(id)"><span>{{icon}}</span>{{n}}<b v-if="id==='review'&&pending.length">{{pending.length}}</b></button></nav><div class="sidebar-note"><span class="dot"></span>{{preview?'本地预览环境':'管理服务'}}<small>版本有据，发布可回退</small></div></aside>
  <main><header><div class="breadcrumb">工作空间 <span>/</span> {{title}}</div><div class="identity"><span>{{roleNames[state.user.role]}}</span><span>{{state.user.username}}</span><button @click="refresh" :disabled="loading">刷新</button><button @click="logout" :disabled="busy">退出</button></div></header>
   <div v-if="preview" class="environment"><span>本地预览</span><p>管理数据已持久化；实体设备和生产用户数据未接入。</p><select aria-label="切换预览身份" :value="state.user.role" @change="previewLogin(($event.target as HTMLSelectElement).value as Role)" :disabled="busy"><option v-for="(n,r) in roleNames" :key="r" :value="r">{{n}}</option></select></div>
   <div class="body"><div class="page-heading"><div><span class="eyebrow">CHARACTER WORKSHOP</span><h1>{{title}}</h1></div><span class="badge">{{state.channels.find(c=>c.name==='preview')?.release_id?'预览已发布':'尚未发布'}}</span></div>
   <p v-if="error" class="error" role="alert">{{error}}<button @click="error=''">关闭</button></p><p v-if="notice" class="notice" role="status">{{notice}}<button @click="notice=''">关闭</button></p><p v-if="loading" class="muted" aria-live="polite">正在读取…</p>
   <template v-if="page==='overview'">
    <section class="hero"><span class="eyebrow">从一份素材，到一次回应</span><h2>让每次发布，都有来处。</h2><p>先创建版本，再独立审核；在预览中确认，保留每次变化。</p><button class="primary" @click="route('asset')">从素材开始 →</button></section>
    <div class="metrics"><article><span>内容对象</span><strong>{{state.objects.length}}</strong><small>素材／角色／内容／事件</small></article><article><span>待审核</span><strong>{{pending.length}}</strong><small>等待独立审核</small></article><article><span>发布版本</span><strong>{{state.releases.length}}</strong><small>不可变发布清单</small></article><article><span>预览执行</span><strong>{{state.executions.length}}</strong><small>当前返回的最近记录</small></article></div>
    <div class="two-columns"><section class="panel"><h2>内容生产路径</h2><div class="flow"><button v-for="[id,n] in [['asset','01 素材'],['character','02 角色'],['content','03 内容'],['event','04 事件']]" :key="id" @click="route(id)">{{n}}<span>打开 →</span></button></div><p class="muted">各版本先审核通过，再成为下一层的引用。</p></section><section class="panel"><h2>环境与接入</h2><div v-for="c in state.channels" :key="c.name" class="list-row"><span>{{c.name==='preview'?'预览环境':'测试环境'}}</span><span class="badge">{{c.release_id?'已发布':'空环境'}}</span></div><div class="list-row"><span>实体手办／App 业务数据</span><span class="muted">尚未接入</span></div></section></div>
   </template>
   <template v-else-if="isKind">
    <div class="editor-layout"><section class="panel"><div class="section-top"><h2>{{kindNames[page as Kind]}}版本</h2><button v-if="can('write')" @click="selected='';resetForm()">＋新建</button></div><p v-if="!objects.length" class="empty">还没有{{kindNames[page as Kind]}}，从右侧创建第一份。</p><div v-for="o in objects" :key="o.id" class="object"><h3>{{o.name}}</h3><button v-for="r in state.revisions.filter(r=>r.object_id===o.id)" :key="r.id" class="version-row" :class="{chosen:selected===r.id}" @click="choose(r)"><span>v{{r.number}} <small>{{r.creator}}</small></span><span class="status" :data-state="r.state">{{stateNames[r.state]}}</span></button></div></section>
    <section class="panel editor"><div class="section-top"><h2>{{current?'版本详情 / 新版本':'新建'+kindNames[page as Kind]}}</h2><span v-if="current" class="status" :data-state="current.state">{{stateNames[current.state]}}</span></div>
     <div v-if="current" class="version-detail"><img v-if="safeImage(current)" class="asset-preview" :src="imageURL(current.payload.digest)" :alt="current.name"><p v-if="current.kind==='asset'" class="muted">{{current.payload.filename}} · {{(Number(current.payload.size)/1024/1024).toFixed(2)}} MB<br><code>{{current.payload.digest}}</code><br><a :href="imageURL(current.payload.digest)" target="_blank" rel="noopener">打开素材文件</a></p><p v-if="current.review_note" class="muted">审核意见：{{current.review_note}}</p><button v-if="current.state==='draft'&&can('write')" @click="submit(current)" :disabled="busy">提交此版本审核</button></div>
     <form @submit.prevent="save"><fieldset :disabled="busy||!can('write')"><label>名称<input v-model="form.name" maxlength="100" required></label>
      <template v-if="page==='asset'"><label>素材文件<input ref="fileInput" type="file" accept=".png,.jpg,.jpeg,.glb" @change="file=($event.target as HTMLInputElement).files?.[0]||null" required></label><p class="muted">PNG / JPEG / GLB，最多 32MB。已保存素材不会被覆盖。</p></template>
      <template v-if="page==='character'"><label>角色设定<textarea v-model="form.persona" maxlength="3000" rows="5" required placeholder="基础性格、关系和表达边界"></textarea></label><label>音色标识<input v-model="form.voice" maxlength="100" required></label><label>素材版本<select v-model="form.asset_revision" required><option value="" disabled>请选择已批准素材</option><option v-for="r in approvedOf('asset')" :key="r.id" :value="r.id">{{label(r)}}</option></select></label></template>
      <template v-if="page==='content'"><label>角色版本<select v-model="form.character_revision" required><option value="" disabled>请选择已批准角色</option><option v-for="r in approvedOf('character')" :key="r.id" :value="r.id">{{label(r)}}</option></select></label><label>内容正文<textarea v-model="form.text" rows="7" maxlength="6000" required placeholder="用户在这个事件中会读到的内容"></textarea></label></template>
      <template v-if="page==='event'"><label>内容版本<select v-model="form.content_revision" required><option value="" disabled>请选择已批准内容</option><option v-for="r in approvedOf('content')" :key="r.id" :value="r.id">{{label(r)}}</option></select></label><label>触发配置<select v-model="form.trigger"><option value="manual">用户操作</option><option value="daily_time">日常时点</option><option value="game_hook">游戏 Hook</option></select></label><label v-if="form.trigger==='daily_time'">时点（上海时区）<input v-model="form.local_time" type="time" required></label><label v-if="form.trigger==='game_hook'">Hook 标识<input v-model="form.hook" required maxlength="80"></label><div class="form-row"><label>冷却秒数<input v-model="form.cooldown_seconds" type="number" min="0" max="86400" required></label><label>有效期秒数<input v-model="form.ttl_seconds" type="number" min="1" max="86400" required></label></div><p class="muted">执行目标：App 本地消费预览。时点／Hook 已保存，自动调度与实体播放尚未接入。</p></template>
      <button v-if="can('write')" class="primary">{{busy?'保存中…':current?'另存新草稿版本':'保存草稿版本'}}</button></fieldset></form>
      <p v-if="!can('write')" class="muted">当前身份可以查看；编辑需内容编辑权限。</p>
    </section></div>
   </template>
   <template v-else-if="page==='review'"><div class="editor-layout"><section class="panel"><h2>待审核 · {{pending.length}}</h2><p v-if="!pending.length" class="empty">没有待审核版本。</p><button v-for="r in pending" :key="r.id" class="review-row" :class="{chosen:selected===r.id}" @click="choose(r)"><span>{{r.name}}<small>{{kindNames[r.kind]}} · v{{r.number}} · {{r.creator}}</small></span><span>查看 →</span></button></section><section class="panel"><template v-if="current"><h2>{{current.name}} · v{{current.number}}</h2><img v-if="safeImage(current)" class="asset-preview" :src="imageURL(current.payload.digest)" :alt="current.name"><dl class="details"><template v-for="(v,k) in current.payload" :key="k"><dt>{{k}}</dt><dd>{{String(k).endsWith('_revision')?revisionName(String(v)):v}}</dd></template></dl><p class="muted">创建人：{{current.creator}} · {{stamp(current.created_at)}}</p><form v-if="can('review')&&current.state==='in_review'" @submit.prevent="review('approved')"><label>审核意见<textarea v-model="reviewNote" required maxlength="500" rows="3"></textarea></label><p v-if="current.created_by===state.user.id" class="error">不能审核自己创建的版本，请换独立审核身份。</p><div class="actions"><button class="primary" :disabled="busy||current.created_by===state.user.id">通过审核</button><button type="button" class="danger" :disabled="busy||!reviewNote.trim()||current.created_by===state.user.id" @click="review('rejected')">驳回</button></div></form><p v-else class="muted">当前身份无审核权限，或此版本审核已结束。</p></template><p v-else class="empty">选择一个版本，核对内容与引用后审核。</p></section></div></template>
   <template v-else-if="page==='publish'"><div class="two-columns"><section class="panel"><h2>创建发布</h2><form @submit.prevent="publish"><fieldset :disabled="busy||!can('publish')"><label>目标环境<select v-model="channel"><option value="preview">预览</option><option value="staging">测试</option></select></label><label>发布名称<input v-model="releaseName" required maxlength="100" placeholder="小鲸基础回应 v1"></label><label>发布说明<textarea v-model="releaseReason" required maxlength="500" rows="2"></textarea></label><div class="revision-selection"><label v-for="r in approved" :key="r.id" class="checkbox"><input v-model="checked" type="checkbox" :value="r.id"><span>{{label(r)}}<small>{{kindNames[r.kind]}}</small></span></label><p v-if="!approved.length" class="empty">先完成内容审核。</p></div><p class="muted">选择入口版本即可自动带入完整依赖。审核未通过或依赖冲突会阻止发布。</p><button class="primary" :disabled="!checked.length">核对并发布</button></fieldset></form></section><section class="panel"><h2>环境当前版本</h2><template v-if="published"><h3>{{published.name}}</h3><p class="muted">{{published.manifest.length}} 个版本 · {{stamp(published.created_at)}}</p><div v-for="item in published.manifest" :key="item.revision_id" class="list-row"><span>{{kindNames[item.kind]}} · {{item.name}}</span><span>v{{item.number}}</span></div><button v-if="can('publish')" class="danger" @click="confirm('下架当前环境','withdraw',{channel,expected_release_id:currentChannel?.release_id})">下架</button></template><p v-else class="empty">此环境未发布内容。</p><h3>发布历史</h3><div v-for="r in state.releases.filter(r=>state!.history.some(h=>h.channel===channel&&h.release_id===r.id))" :key="r.id" class="history-row"><div>{{r.name}}<small>{{stamp(r.created_at)}}</small></div><button v-if="can('publish')&&r.id!==currentChannel?.release_id" @click="confirm('回退到 '+r.name,'rollback',{channel,release_id:r.id,expected_release_id:currentChannel?.release_id||null})">回退</button><span v-else-if="r.id===currentChannel?.release_id" class="badge">当前</span></div></section></div></template>
   <template v-else-if="page==='runtime'"><section class="panel runtime"><div class="section-top"><h2>读取已发布快照</h2><select v-model="channel" aria-label="消费环境"><option value="preview">预览环境</option><option value="staging">测试环境</option></select></div><template v-if="runtimeRelease"><h3>{{runtimeRelease.name}}</h3><div class="runtime-characters"><article v-for="r in runtimeRelease.manifest.filter(r=>r.kind==='character')" :key="r.revision_id"><img v-if="runtimeRelease.manifest.find(x=>x.revision_id===r.payload.asset_revision)?.payload.media_type.toString().startsWith('image/')" :src="imageURL(runtimeRelease.manifest.find(x=>x.revision_id===r.payload.asset_revision)?.payload.digest)" :alt="r.name"><h2>{{r.name}}</h2><p>{{r.payload.persona}}</p></article></div><div class="actions"><button v-for="e in runtimeRelease.manifest.filter(r=>r.kind==='event')" :key="e.revision_id" class="primary" :disabled="busy||!can('execute')" @click="execute(e.revision_id)">▷ {{e.name}}</button></div><div v-if="lastExecution" class="reply"><span>{{lastExecution.character}}</span><p>{{lastExecution.text}}</p><small>本地消费预览完成 · 实体设备未执行</small></div></template><p v-else class="empty">此环境未发布；完成审核与发布后再预览。</p></section><section class="panel"><h2>执行记录</h2><div v-for="e in state.executions" :key="e.id" class="history-row"><div>{{e.result.character}}：{{e.result.text}}<small>{{stamp(e.created_at)}}</small></div><span class="badge">预览完成</span></div><p v-if="!state.executions.length" class="empty">暂无执行记录。</p></section></template>
   <template v-else-if="page==='audit'"><section class="panel table-panel"><h2>关键操作记录</h2><div class="table-scroll"><table><thead><tr><th>时间 / 请求</th><th>身份</th><th>操作</th><th>目标</th><th>结果 / 说明</th></tr></thead><tbody><tr v-for="a in state.audit" :key="a.id"><td>{{stamp(a.created_at)}}<small>{{a.request_id}}</small></td><td>{{a.username||'未认证'}}</td><td>{{a.action}}</td><td><code>{{a.target||'—'}}</code></td><td><span class="status" :data-state="a.outcome==='success'?'approved':'rejected'">{{a.outcome==='success'?'成功':'拒绝／失败'}}</span><small>{{a.details.reason||a.details.code||'—'}}</small></td></tr></tbody></table></div><button @click="moreAudit" :disabled="busy">加载更多</button></section></template>
   <template v-else-if="page==='users'"><div v-if="can('users')" class="two-columns"><section class="panel"><h2>创建真实管理员</h2><form @submit.prevent="createUser"><fieldset :disabled="busy"><label>用户名<input v-model="userForm.username" required maxlength="60" autocomplete="off"></label><label>密码<input v-model="userForm.password" type="password" minlength="12" required autocomplete="new-password"></label><label>角色<select v-model="userForm.role"><option v-for="(n,r) in roleNames" :key="r" :value="r">{{n}}</option></select></label><button class="primary">创建管理员</button></fieldset></form></section><section class="panel"><h2>真实账号</h2><div v-for="u in state.users.filter(u=>!u.preview_only)" :key="u.id" class="user-row"><h3>{{u.username}} <span class="badge">{{u.enabled?'启用':'停用'}}</span></h3><select :value="u.role" :disabled="busy||u.id===state.user.id" :aria-label="u.username+'角色'" @change="confirm('更改管理员角色','set_user',{id:u.id,role:($event.target as HTMLSelectElement).value,enabled:!!u.enabled})"><option v-for="(n,r) in roleNames" :key="r" :value="r">{{n}}</option></select><button class="danger" :disabled="busy||u.id===state.user.id" @click="confirm(u.enabled?'停用管理员':'启用管理员','set_user',{id:u.id,role:u.role,enabled:!u.enabled})">{{u.enabled?'停用':'启用'}}</button></div><p v-if="!state.users.some(u=>!u.preview_only)" class="empty">暂无真实账号；预览身份与真实账号分开。</p><p class="muted">权限变更会撤销该账号已有会话。</p></section></div><p v-else class="error">当前身份无管理员管理权限。</p></template>
   </div>
  </main>
 </div>
 <dialog ref="dialog"><form @submit.prevent="confirmed"><span class="eyebrow">确认操作</span><h2>{{confirmation?.title}}</h2><p>发布指针或账号状态将发生变更，操作会记录。</p><label>操作原因<textarea v-model="reason" required maxlength="500" rows="3"></textarea></label><p v-if="error" class="error">{{error}}</p><div class="actions"><button type="button" @click="dialog?.close()" :disabled="busy">取消</button><button class="primary" :disabled="busy">{{busy?'处理中…':'确认执行'}}</button></div></form></dialog>
</template>
